function goalKey(v){return v>=11?11:v>=10?10:v>=9?9:v>=8?8:v>=7?7:v>=6?6:v>=5?5:v>=4?4:Math.max(1,Math.floor(v+1e-9))}
function gl(v){const n=Math.floor(v+1e-9),f=v-n;const s=['','초1','초2','초3','초4','초5','초6','중1','중2','중3','고1','고2'][Math.min(11,n)];return n>=4&&n<=6?s+(f>=.45?' 2학기':' 1학기'):s}
function glShort(v){return ['','초1','초2','초3','초4','초5','초6','중1','중2','중3','고1','고2'][Math.min(11,Math.floor(v+1e-9))]}
